"""The query bounds the web app needs, rendered as TypeScript.

The web app must not copy backend values by hand, so ``apps/web/src/lib/limits.ts`` is
generated from ``compass_core.contract.params`` (``make gen-api``), and a test fails
when the committed file is out of date.
"""

from __future__ import annotations

from compass_core.contract import params

WEB_LIMITS_PATH = "apps/web/src/lib/limits.ts"
"""Where the generated file lives, relative to the repository root."""

_EXPORTS: tuple[tuple[str, str, int | float], ...] = (
    ("MAX_DEPTH", "Largest traversal depth the impact query accepts.", params.MAX_DEPTH),
    (
        "DEFAULT_IMPACT_DEPTH",
        "Impact traversal depth when none is chosen.",
        params.DEFAULT_IMPACT_DEPTH,
    ),
    ("MAX_LIMIT", "Largest result limit a query accepts.", params.MAX_LIMIT),
    ("DEFAULT_LIMIT", "Result limit when none is chosen.", params.DEFAULT_LIMIT),
    (
        "MAX_TEXT_LENGTH",
        "Longest search text or symbol reference, in characters.",
        params.MAX_TEXT_LENGTH,
    ),
)


def render_web_limits() -> str:
    """Render ``limits.ts`` from the contract's parameter bounds.

    Returns:
        The full TypeScript module, one documented ``export const`` per bound.

    Example:
        The output contains ``export const MAX_DEPTH = 10;`` when
        ``params.MAX_DEPTH == 10``.
    """
    lines = [
        "// Generated by `make gen-api` from compass_core.contract.params. Do not edit.",
        "",
    ]
    for name, doc, value in _EXPORTS:
        lines += [f"/** {doc} */", f"export const {name} = {value};", ""]
    return "\n".join(lines)
